IF DB_ID('EmployeeDB') IS NULL
BEGIN
    CREATE DATABASE EmployeeDB;
END;
GO
USE EmployeeDB;
GO

USE EmployeeDB;
GO

IF OBJECT_ID('dbo.Departments', 'U') IS NOT NULL
    DROP TABLE dbo.Departments;
IF OBJECT_ID('dbo.Employees', 'U') IS NOT NULL
    DROP TABLE dbo.Employees;
GO

CREATE TABLE dbo.Departments (
    DepartmentID INT IDENTITY(1,1) PRIMARY KEY,
    DepartmentName NVARCHAR(50) NOT NULL
);

CREATE TABLE dbo.Employees (
    EmployeeID INT IDENTITY(1,1) PRIMARY KEY,
    FirstName NVARCHAR(50) NOT NULL,
    LastName NVARCHAR(50) NOT NULL,
    DepartmentID INT NOT NULL FOREIGN KEY REFERENCES dbo.Departments(DepartmentID),
    HireDate DATE NOT NULL
);
GO

USE EmployeeDB;
GO

SELECT e.EmployeeID, e.FirstName, e.LastName, d.DepartmentName, e.HireDate
FROM dbo.Employees e
JOIN dbo.Departments d ON e.DepartmentID = d.DepartmentID;
GO
